get_checkout_page.code:
final response = await client.checkoutPage.getCheckoutPage();
final checkoutPage = (response.map as Map)['checkout_page'] as Map;
print(checkoutPage['customer_checkout']);
print(checkoutPage['order_summary']);

patch_checkout_page.code:
final response = await client.checkoutPage.patchCheckoutPage({
  'checkout_page': {
    'order_summary': {'enable_payment_expand_view': false},
    'customer_checkout': {'multiple_shipping_methods': true},
  },
});
final checkoutPage = (response.map as Map)['checkout_page'] as Map;
print(checkoutPage['order_summary']);
print(checkoutPage['customer_checkout']);

get_checkout_page_section.code:
final response =
    await client.checkoutPage.getCheckoutPageSection('order_summary');
